/// @file rt_client.cpp
/// @brief Implementation of the typed BC-side RemoteTerminal client.
/// @details Auto-generated by Exhibition from the device set.
///          Regenerated on every run; edit the .ioc and rerun rather
///          than hand-editing this file.

#include "rt_client.h"

#include <cstdio>
#include <cstring>

#include "communication/message_header.h"
#include "host/logger.h"

namespace {

struct BlockingCtx {
    Status   status;
    bool     done;
    uint8_t* user_out_buf;
    uint32_t user_out_cap;
    uint32_t* user_out_len_opt;
    bool     has_remote;          ///< True if the RT fault frame carried a payload.
    uint8_t  remote_domain;       ///< FaultDomain tag (byte 0 of the fault payload).
    uint8_t  remote_code;         ///< Reason code within that domain (byte 1).
};


void blocking_completion(Status s,
                         const MessageHeader& /*resp_header*/,
                         uint8_t const* payload,
                         uint32_t len,
                         void* user)
{
    BlockingCtx* ctx = static_cast<BlockingCtx*>(user);
    ctx->status = s;
    // RT fault frames are self-describing: byte 0 is a FaultDomain tag and
    // byte 1 the reason code within that domain. Capture both so run_one can
    // decode the remote reason with the right table (Status for Protocol).
    if (s == Status::RemoteFault && payload != nullptr && len >= 1u) {
        ctx->remote_domain = payload[0];
        ctx->remote_code   = (len >= 2u) ? payload[1] : 0u;
        ctx->has_remote    = true;
    }
    if (ctx->user_out_buf != nullptr && payload != nullptr && len > 0u) {
        const uint32_t n = (len < ctx->user_out_cap) ? len : ctx->user_out_cap;
        std::memcpy(ctx->user_out_buf, payload, n);
    }
    if (ctx->user_out_len_opt != nullptr) {
        *ctx->user_out_len_opt = len;
    }
    ctx->done = true;
}


/// @brief Log an operation's outcome: INFO on success, ERROR otherwise.
/// @details When the RT reports a fault its payload names a FaultDomain (byte 0)
///          and a reason code (byte 1). Pass them via has_remote/remote_domain/
///          remote_code to append the decoded remote reason. A Protocol-domain
///          code is rendered as a Status name ("-> RemoteFault (remote:
///          PayloadTooLarge)"); any other domain is rendered as a domain name
///          plus a hex code ("-> RemoteFault (remote: App 0xCA)").
void log_op(Logger& log, const Request& req, Status status,
            bool has_remote = false, uint8_t remote_domain = 0u,
            uint8_t remote_code = 0u, char const* note = nullptr)
{
    uint8_t const* cmd = (req.cmd_len > kInlinePayloadBytes) ? req.cmd_ext
                                                             : req.cmd_inline;
    const uint8_t op = (req.cmd_len > 0u && cmd != nullptr) ? cmd[0] : 0u;
    char buf[160];
    int n;
    if (has_remote) {
        char remote[48];
        if (remote_domain == static_cast<uint8_t>(FaultDomain::Protocol)) {
            std::snprintf(remote, sizeof(remote), "%s",
                          status_to_string(static_cast<Status>(remote_code)));
        } else {
            std::snprintf(remote, sizeof(remote), "%s 0x%02X",
                          fault_domain_to_string(
                              static_cast<FaultDomain>(remote_domain)),
                          static_cast<unsigned>(remote_code));
        }
        n = std::snprintf(buf, sizeof(buf), "op sa=%s %s -> %s (remote: %s)",
                          sub_address_name(req.sub_address),
                          op_name(req.sub_address, op),
                          status_to_string(status),
                          remote);
    } else {
        n = std::snprintf(buf, sizeof(buf), "op sa=%s %s -> %s",
                          sub_address_name(req.sub_address),
                          op_name(req.sub_address, op),
                          status_to_string(status));
    }
    // Optional trailing note (e.g. a host-stall attribution on a timeout).
    if (note != nullptr && n > 0 && static_cast<size_t>(n) < sizeof(buf)) {
        std::snprintf(buf + n, sizeof(buf) - static_cast<size_t>(n), " %s", note);
    }
    log.line(status == Status::Ok ? "INFO" : "ERROR", buf);
}


/// @brief Submit `req` and spin tick() until the completion callback fires.
/// @details
/// The BC self-enforces kFrameTimeoutMs per wire frame; the outer
/// 8x guard is a safety net in case the state machine itself stalls. The
/// final Status is logged on every exit path so detected errors (Timeout,
/// CrcFail*, QueueFull, ...) land in the log even though the wire-level
/// LoggingFrameTransport only sees raw bytes.
Status run_one(BusController& bc,
                  IClock& clock,
                  const Request& req,
                  uint8_t* out_buf,
                  uint32_t out_cap,
                  uint32_t* out_len_opt,
                  Logger& log)
{
    BlockingCtx ctx;
    ctx.status            = Status::Ok;
    ctx.done              = false;
    ctx.user_out_buf      = out_buf;
    ctx.user_out_cap      = out_cap;
    ctx.user_out_len_opt  = out_len_opt;
    ctx.has_remote        = false;
    ctx.remote_domain     = 0u;
    ctx.remote_code       = 0u;

    Status submit_status = Status::Ok;
    if (!bc.submit(req, &blocking_completion, &ctx, submit_status)) {
        log_op(log, req, submit_status);
        return submit_status;
    }

    const uint32_t start = clock.now_ms();
    constexpr uint32_t kOuterTimeoutMs = 8u * kFrameTimeoutMs;
    uint32_t max_tick_ms = 0u;
    while (!ctx.done) {
        const uint32_t t0 = clock.now_ms();
        bc.tick();
        const uint32_t tick_ms = clock.now_ms() - t0;
        if (tick_ms > max_tick_ms) {
            max_tick_ms = tick_ms;
        }
        if ((clock.now_ms() - start) > kOuterTimeoutMs) {
            // tick() never blocks on the transport (non-blocking I/O) and the
            // bus self-times-out every kFrameTimeoutMs, so any single tick that
            // ran longer than a whole frame budget means the host -- not the
            // bus -- stalled the poll loop (a blocked syscall, scheduler
            // preemption, ...). Call that out so the log is unambiguous.
            if (max_tick_ms > kFrameTimeoutMs) {
                char note[64];
                std::snprintf(note, sizeof(note),
                              "(host stall %u ms -- not a bus fault)",
                              static_cast<unsigned>(max_tick_ms));
                log_op(log, req, Status::Timeout, false, 0u, 0u, note);
            } else {
                log_op(log, req, Status::Timeout);
            }
            return Status::Timeout;
        }
    }
    log_op(log, req, ctx.status, ctx.has_remote, ctx.remote_domain,
           ctx.remote_code);
    return ctx.status;
}


/// @brief Stage `actual_len` cmd bytes into req.cmd_inline, zero-pad up to
///        the wire slot, and stamp req.cmd_len / req.cmd_size accordingly.
/// @pre `actual_len <= kInlinePayloadBytes`.
void stage_inline_cmd(Request& req, uint32_t actual_len)
{
    const PayloadSizes ps  = bytes_to_payload_size(actual_len);
    const uint32_t slot    = payload_size_to_bytes(ps);
    if (slot > actual_len) {
        std::memset(req.cmd_inline + actual_len, 0, slot - actual_len);
    }
    req.cmd_len  = slot;
    req.cmd_size = ps;
    req.cmd_ext  = nullptr;
}

} // namespace


char const* status_to_string(Status s)
{
    switch (s) {
        case Status::Ok:                 return "Ok";
        case Status::QueueFull:          return "QueueFull";
        case Status::InvalidSubAddress:  return "InvalidSubAddress";
        case Status::PayloadTooLarge:    return "PayloadTooLarge";
        case Status::Timeout:            return "Timeout";
        case Status::RemoteFault:        return "RemoteFault";
        case Status::CrcFailHeader:      return "CrcFailHeader";
        case Status::CrcFailPayload:     return "CrcFailPayload";
        case Status::TransportError:     return "TransportError";
        case Status::HandlerError:       return "HandlerError";
    }
    return "Unknown";
}

char const* fault_domain_to_string(FaultDomain d)
{
    switch (d) {
        case FaultDomain::Protocol: return "Protocol";
        case FaultDomain::Hal:      return "Hal";
        case FaultDomain::App:      return "App";
    }
    return "Unknown";
}

char const* op_name(uint8_t sub_address, uint8_t opcode)
{
    switch (sub_address) {
        case 1: // System
            switch (opcode) {
                case 0x00: return "GET_SERVICE_HASH";
                case 0x01: return "GET_FINGERPRINT";
                case 0x02: return "GET_DEVICE_COUNT";
                case 0x03: return "GET_SYS_TICK";
                case 0x04: return "GET_CORE_DEVICE_ID";
                case 0x05: return "GET_CPU_ID";
                case 0x06: return "SYNC_PROBE";
                case 0x07: return "SYNC_FINAL";
                case 0x08: return "SYNC_ADJUST";
                case 0x09: return "GET_MESSAGE_FAULT_COUNTER";
                case 0x0A: return "SOFT_RESET";
                case 0x0B: return "READ_MEMORY";
                default: return "UNKNOWN";
            }
        case 2: // adc
            switch (opcode) {
                case 0x00: return "GET_SERVICE_HASH";
                case 0x01: return "SAMPLE";
                default: return "UNKNOWN";
            }
        case 3: // can
            switch (opcode) {
                case 0x00: return "GET_SERVICE_HASH";
                case 0x01: return "TX_FRAME";
                case 0x02: return "RX_FRAME";
                default: return "UNKNOWN";
            }
        case 4: // gpio_in
            switch (opcode) {
                case 0x00: return "GET_SERVICE_HASH";
                case 0x01: return "READ";
                default: return "UNKNOWN";
            }
        case 5: // gpio_in
            switch (opcode) {
                case 0x00: return "GET_SERVICE_HASH";
                case 0x01: return "READ";
                default: return "UNKNOWN";
            }
        case 6: // gpio_out
            switch (opcode) {
                case 0x00: return "GET_SERVICE_HASH";
                case 0x01: return "SET";
                case 0x02: return "CLEAR";
                default: return "UNKNOWN";
            }
        case 7: // gpio_out
            switch (opcode) {
                case 0x00: return "GET_SERVICE_HASH";
                case 0x01: return "SET";
                case 0x02: return "CLEAR";
                default: return "UNKNOWN";
            }
        case 8: // gpio_out
            switch (opcode) {
                case 0x00: return "GET_SERVICE_HASH";
                case 0x01: return "SET";
                case 0x02: return "CLEAR";
                default: return "UNKNOWN";
            }
        case 9: // i2c
            switch (opcode) {
                case 0x00: return "GET_SERVICE_HASH";
                case 0x01: return "WRITE_REG";
                case 0x02: return "READ_REG";
                default: return "UNKNOWN";
            }
        case 10: // rtc
            switch (opcode) {
                case 0x00: return "GET_SERVICE_HASH";
                case 0x01: return "SET_DATETIME";
                case 0x02: return "GET_DATETIME";
                default: return "UNKNOWN";
            }
        case 11: // spi
            switch (opcode) {
                case 0x00: return "GET_SERVICE_HASH";
                case 0x01: return "TX";
                case 0x02: return "RX";
                default: return "UNKNOWN";
            }
        default: return "UNKNOWN";
    }
}

char const* sub_address_name(uint8_t sub_address)
{
    switch (sub_address) {
        case 1: return "system";
        case 2: return "adc_hadc1_ch1";
        case 3: return "can_hcan1";
        case 4: return "gpio_in_bank_B";
        case 5: return "gpio_in_bank_D";
        case 6: return "gpio_out_bank_C";
        case 7: return "gpio_out_bank_D";
        case 8: return "gpio_out_bank_E";
        case 9: return "i2c_hi2c1";
        case 10: return "rtc";
        case 11: return "spi_hspi1";
        default: return "UNKNOWN";
    }
}

void LoggerFaultObserver::on_fault(uint8_t sub_addr, Status status, bool will_retry)
{
    // A terminal failure is already reported as an ERROR by the operation's
    // completion logging, so only surface the recoverable attempts (the ones
    // the BC is about to retry) here -- those would otherwise leave no trace.
    if (!will_retry) {
        return;
    }
    char buf[128];
    std::snprintf(buf, sizeof(buf), "sa=%s attempt failed: %s -- retrying",
                  sub_address_name(sub_addr),
                  status_to_string(status));
    m_log.line("WARN", buf);
}

AdcClient::AdcClient(BusController& bc, IClock& clock, Logger& log, SubAddress sub_address)
    : m_bc(bc)
    , m_clock(clock)
    , m_log(log)
    , m_sa(sub_address)
{
}


Status AdcClient::sample(uint16_t& counts_out, uint32_t& timestamp_ms_out)
{
    Request req{};
    req.sub_address = static_cast<uint8_t>(m_sa);
    req.priority    = MessagePriorities::Medium;
    req.is_read     = true;
    req.cmd_inline[0] = static_cast<uint8_t>(AdcCmd::Sample);
    stage_inline_cmd(req, 1u);
    req.resp_buf_max = 16u;
    req.resp_ext     = nullptr;

    uint8_t  resp[16] = {0};
    uint32_t got      = 0u;
    const Status s = run_one(m_bc, m_clock, req, resp, sizeof(resp), &got, m_log);
    if (s == Status::Ok && got >= 6u) {
        counts_out = static_cast<uint16_t>(resp[0])
                   | (static_cast<uint16_t>(resp[1]) << 8);
        timestamp_ms_out =
              (static_cast<uint32_t>(resp[2]))
            | (static_cast<uint32_t>(resp[3]) <<  8)
            | (static_cast<uint32_t>(resp[4]) << 16)
            | (static_cast<uint32_t>(resp[5]) << 24);
    }
    return s;
}



CanClient::CanClient(BusController& bc, IClock& clock, Logger& log, SubAddress sub_address)
    : m_bc(bc)
    , m_clock(clock)
    , m_log(log)
    , m_sa(sub_address)
{
}


Status CanClient::tx_frame(uint32_t id, uint8_t dlc, const uint8_t data[8])
{
    if (dlc > 8u || (data == nullptr && dlc > 0u)) {
        return Status::HandlerError;
    }
    Request req{};
    req.sub_address = static_cast<uint8_t>(m_sa);
    req.priority    = MessagePriorities::Medium;
    req.is_read     = false;
    req.cmd_inline[0] = static_cast<uint8_t>(CanCmd::TxFrame);
    // CAN id is big-endian on the wire (matches can_handler.cpp).
    req.cmd_inline[1] = static_cast<uint8_t>((id >> 24) & 0xFFu);
    req.cmd_inline[2] = static_cast<uint8_t>((id >> 16) & 0xFFu);
    req.cmd_inline[3] = static_cast<uint8_t>((id >>  8) & 0xFFu);
    req.cmd_inline[4] = static_cast<uint8_t>( id        & 0xFFu);
    req.cmd_inline[5] = dlc;
    for (uint8_t i = 0; i < dlc; ++i) {
        req.cmd_inline[6u + i] = data[i];
    }
    stage_inline_cmd(req, 6u + static_cast<uint32_t>(dlc));
    req.resp_buf_max = 0u;
    req.resp_ext     = nullptr;
    return run_one(m_bc, m_clock, req, nullptr, 0u, nullptr, m_log);
}


Status CanClient::rx_frame(uint32_t& id_out, uint8_t& dlc_out, uint8_t data_out[8])
{
    if (data_out == nullptr) {
        return Status::HandlerError;
    }
    Request req{};
    req.sub_address = static_cast<uint8_t>(m_sa);
    req.priority    = MessagePriorities::Medium;
    req.is_read     = true;
    req.cmd_inline[0] = static_cast<uint8_t>(CanCmd::RxFrame);
    stage_inline_cmd(req, 1u);
    req.resp_buf_max = 16u;
    req.resp_ext     = nullptr;

    uint8_t  resp[16] = {0};
    uint32_t got      = 0u;
    const Status s = run_one(m_bc, m_clock, req, resp, sizeof(resp), &got, m_log);
    if (s == Status::Ok && got >= 13u) {
        id_out  = (static_cast<uint32_t>(resp[0]) << 24)
                | (static_cast<uint32_t>(resp[1]) << 16)
                | (static_cast<uint32_t>(resp[2]) <<  8)
                |  static_cast<uint32_t>(resp[3]);
        dlc_out = resp[4];
        std::memcpy(data_out, resp + 5, 8);
    }
    return s;
}



GpioInputClient::GpioInputClient(BusController& bc, IClock& clock, Logger& log, SubAddress sub_address, uint8_t pin_index)
    : m_bc(bc)
    , m_clock(clock)
    , m_log(log)
    , m_sa(sub_address)
    , m_pin_idx(pin_index)
{
}


Status GpioInputClient::read(bool& value_out)
{
    Request req{};
    req.sub_address = static_cast<uint8_t>(m_sa);
    req.priority    = MessagePriorities::Medium;
    req.is_read     = true;
    req.cmd_inline[0] = static_cast<uint8_t>(GpioInputCmd::Read);
    req.cmd_inline[1] = m_pin_idx;
    stage_inline_cmd(req, 2u);
    req.resp_buf_max = 16u;
    req.resp_ext     = nullptr;

    uint8_t  resp[16] = {0};
    uint32_t got      = 0u;
    const Status s = run_one(m_bc, m_clock, req, resp, sizeof(resp), &got, m_log);
    if (s == Status::Ok && got >= 1u) {
        value_out = (resp[0] != 0u);
    }
    return s;
}



