Status RtClient::get_api_fingerprint(uint32_t& fingerprint_out)
{
    Request req{};
    req.sub_address  = static_cast<uint8_t>(SubAddress::System);
    req.priority     = MessagePriorities::Low;
    req.is_read      = true;
    req.cmd_inline[0] = static_cast<uint8_t>(SystemCmd::GetFingerprint);
    stage_inline_cmd(req, 1u);
    req.resp_buf_max = 16u;
    req.resp_ext     = nullptr;

    uint8_t  resp[16] = {0};
    uint32_t got      = 0u;
    const Status s = run_one(m_bc, m_clock, req, resp, sizeof(resp), &got, m_log);
    if (s == Status::Ok && got >= 4u) {
        fingerprint_out =
              (static_cast<uint32_t>(resp[0]))
            | (static_cast<uint32_t>(resp[1]) <<  8)
            | (static_cast<uint32_t>(resp[2]) << 16)
            | (static_cast<uint32_t>(resp[3]) << 24);
    }
    return s;
}


