Status RtClient::read_memory(uint32_t address, uint16_t len, uint8_t* data_out)
{
    if (data_out == nullptr && len > 0u) {
        return Status::HandlerError;
    }
    if (static_cast<uint32_t>(len) > kMaxPayloadBytes) {
        return Status::PayloadTooLarge;
    }

    Request req{};
    req.sub_address = static_cast<uint8_t>(SubAddress::System);
    req.priority    = MessagePriorities::Medium;
    req.is_read     = true;
    req.cmd_inline[0] = static_cast<uint8_t>(SystemCmd::ReadMemory);
    req.cmd_inline[1] = static_cast<uint8_t>( address        & 0xFFu);
    req.cmd_inline[2] = static_cast<uint8_t>((address >>  8)  & 0xFFu);
    req.cmd_inline[3] = static_cast<uint8_t>((address >> 16)  & 0xFFu);
    req.cmd_inline[4] = static_cast<uint8_t>((address >> 24)  & 0xFFu);
    req.cmd_inline[5] = static_cast<uint8_t>( len             & 0xFFu);
    req.cmd_inline[6] = static_cast<uint8_t>((len >> 8)       & 0xFFu);
    stage_inline_cmd(req, 7u);

    const PayloadSizes resp_ps = bytes_to_payload_size(len);
    const uint32_t resp_slot   = payload_size_to_bytes(resp_ps);
    req.resp_buf_max = resp_slot;

    uint8_t inline_resp[kInlinePayloadBytes] = {0};
    uint8_t scratch[kMaxPayloadBytes];
    const bool use_ext = (resp_slot > kInlinePayloadBytes);
    req.resp_ext = use_ext ? scratch : nullptr;

    uint8_t* sink = use_ext ? scratch : inline_resp;
    uint32_t cap  = use_ext ? sizeof(scratch) : sizeof(inline_resp);
    uint32_t got  = 0u;
    const Status s = run_one(m_bc, m_clock, req, sink, cap, &got, m_log);
    if (s == Status::Ok && len > 0u) {
        const uint32_t n = (got < len) ? got : len;
        std::memcpy(data_out, sink, n);
    }
    return s;
}
namespace {

/// @brief Build and run one [opcode, units, uint32 value] sync command
///        against the system sub-address, returning its response bytes.
Status sync_exchange(BusController& bc, IClock& clock, Logger& log,
                     uint8_t opcode, uint8_t units, uint32_t value,
                     uint8_t* resp, uint32_t resp_cap, uint32_t& got)
{
    Request req{};
    req.sub_address  = static_cast<uint8_t>(SubAddress::System);
    req.priority     = MessagePriorities::High;
    req.is_read      = true;
    req.cmd_inline[0] = opcode;
    req.cmd_inline[1] = units;
    emplace_u32_le(req.cmd_inline + 2, value);
    stage_inline_cmd(req, kSyncCmdBytes);
    req.resp_buf_max = resp_cap;
    req.resp_ext     = nullptr;
    got = 0u;
    return run_one(bc, clock, req, resp, resp_cap, &got, log);
}

} // namespace


Status RtClient::sync_once(SyncMeasurement* raw_out)
{
    const uint8_t units = static_cast<uint8_t>(TimeUnits::Millisecond);
    uint8_t  resp[kSyncFinalRespBytes] = {0};
    uint32_t got      = 0u;

    // NTP four-timestamp exchange over a single round trip. MIRRORS the
    // sequence in tests/test_sync_e2e.cpp; keep the two in lockstep.
    // Step 1 (SYNC_PROBE): T1 is the BC clock at send; the RT returns T2 and
    // T3 (receive and response-send instants) and caches T1; T4 is the BC
    // clock when the response arrives. The RT runs the resulting (offset,
    // delay) through a sliding 8-deep min-delay clock filter before it
    // disciplines its clock, so this client just drives the exchange.
    const uint32_t t1 = m_clock.now_ms();
    Status s = sync_exchange(m_bc, m_clock, m_log, static_cast<uint8_t>(SystemCmd::SyncProbe), units, t1,
                             resp, sizeof(resp), got);
    const uint32_t t4 = m_clock.now_ms();
    if (s != Status::Ok || got < kSyncProbeRespBytes) {
        // Record which phase failed, the underlying status, and the short byte
        // count so the persistent log pins the failure mode (complements the
        // LoggingFrameTransport byte dump and run_one's per-op result line).
        char note[96];
        std::snprintf(note, sizeof(note),
                      "sync_once SYNC_PROBE failed: status=%s got=%u (need>=%u)",
                      status_to_string(s), static_cast<unsigned>(got),
                      static_cast<unsigned>(kSyncProbeRespBytes));
        m_log.line("ERROR", note);
        return (s == Status::Ok) ? Status::CrcFailPayload : s;
    }

    // Step 2 (SYNC_FINAL): send T4; the RT computes the path delay and the
    // BC-minus-RT offset from its cached T1, T2, T3 and this T4, runs them
    // through the min-delay clock filter, disciplines its clock from the
    // selected sample, and returns the fixed-point result for the BC view.
    s = sync_exchange(m_bc, m_clock, m_log, static_cast<uint8_t>(SystemCmd::SyncFinal), units, t4,
                      resp, sizeof(resp), got);
    if (s != Status::Ok || got < kSyncFinalRespBytes) {
        char note[96];
        std::snprintf(note, sizeof(note),
                      "sync_once SYNC_FINAL failed: status=%s got=%u (need>=%u)",
                      status_to_string(s), static_cast<unsigned>(got),
                      static_cast<unsigned>(kSyncFinalRespBytes));
        m_log.line("ERROR", note);
        return (s == Status::Ok) ? Status::CrcFailPayload : s;
    }

    const double path_delay = sync_decode_unsigned(
        extract_u32_le(resp), extract_u32_le(resp + 4));
    const double offset = sync_decode_signed(
        static_cast<int32_t>(extract_u32_le(resp + 8)),
        static_cast<int32_t>(extract_u32_le(resp + 12)));

    // The RT returns its recommended offset (already disciplined on the
    // RT clock by its own smoother) and the latest measured path delay;
    // store both directly so this view matches the RT -- no BC-side filter.
    m_offset       = offset;
    m_path_delay   = path_delay;
    m_have_sync    = true;
    m_sync_units   = units;

    if (raw_out != nullptr) {
        raw_out->path_delay_units = path_delay;
        raw_out->offset_units     = offset;
        raw_out->reload_ticks     = m_reload_ticks;
        raw_out->units            = units;
    }
    return Status::Ok;
}


Status RtClient::sync_adjust(SyncAdjustResult* out)
{
    // SYNC_ADJUST is a one-byte trigger: the RT applies a single smoothed, bounded
    // SysTick-reload step from the skew it averaged over the preceding telemetry
    // phase, and replies with that skew and the reload it programmed
    // (kSyncAdjustRespBytes, 8 bytes -> fits the inline response slot).
    Request req{};
    req.sub_address  = static_cast<uint8_t>(SubAddress::System);
    req.priority     = MessagePriorities::Medium;
    req.is_read      = true;
    req.cmd_inline[0] = static_cast<uint8_t>(SystemCmd::SyncAdjust);
    stage_inline_cmd(req, kSyncAdjustCmdBytes);
    req.resp_buf_max = 16u;
    req.resp_ext     = nullptr;

    uint8_t  resp[16] = {0};
    uint32_t got      = 0u;
    const Status s = run_one(m_bc, m_clock, req, resp, sizeof(resp), &got, m_log);
    if (s != Status::Ok || got < kSyncAdjustRespBytes) {
        char note[96];
        std::snprintf(note, sizeof(note),
                      "sync_adjust failed: status=%s got=%u (need>=%u)",
                      status_to_string(s), static_cast<unsigned>(got),
                      static_cast<unsigned>(kSyncAdjustRespBytes));
        m_log.line("ERROR", note);
        return (s == Status::Ok) ? Status::CrcFailPayload : s;
    }

    // Word 0: the averaged skew the RT used (int32 ppb). Word 1: the SysTick reload
    // it programmed. Mirror the reload into reload_ticks() so the BC view stays
    // current after an adjust.
    const int32_t  avg_skew_ppb = static_cast<int32_t>(extract_u32_le(resp));
    const uint32_t reload       = extract_u32_le(resp + 4);
    m_reload_ticks = reload;
    if (out != nullptr) {
        out->avg_skew_ppb = avg_skew_ppb;
        out->reload_ticks = reload;
    }
    return Status::Ok;
}
